// components/Screens/Dashboard/tabs/EvaluationTab/EvaluationTab.tsx
// Evaluation tab UI – matches the Candidate Evaluations screenshot exactly

import React from "react";
import { useNavigate } from "react-router-dom";
import "./EvaluationTab.css";
import { useEvaluationTab } from "../Hooks/useEvaluationTab";
import { EvaluationCandidate } from "../services/InterviewPanelService";

import { userInfo } from "../../../../utilities/hooks/RoleContext";

const EvaluationTab: React.FC = () => {
  const { ADGroupData } = userInfo();
  const currentUserEmailId = ADGroupData?.EmailId?.[0] || ""; // Gets the email from RoleContext
  const navigate = useNavigate();

  const {
    candidates,
    pendingInfo,
    isLoading,
    alert,
    closeAlert,
    handleHover,
    handleEvaluateClick,
    refresh,
  } = useEvaluationTab(currentUserEmailId);

  // ── Evaluate button click ──────────────────────────────────────────────────
  const onEvaluate = async (row: EvaluationCandidate) => {
    await handleEvaluateClick(row, navigate);
  };

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="eval-wrapper">

      {/* Alert banner */}
      {alert.open && (
        <div className={`eval-alert eval-alert--${alert.type.toLowerCase()}`}>
          <span>{alert.message}</span>
          <button className="eval-alert__close" onClick={closeAlert}>
            OK
          </button>
        </div>
      )}

      {/* Main card */}
      <div className="eval-card">

        {/* Card header */}
        <div className="eval-card__header">
          <h2 className="eval-card__title">Candidate Evaluations</h2>
          <button
            className="eval-card__back-btn"
            onClick={() => navigate("/Dashboard")}
          >
            ↺ BACK TO DASHBOARD
          </button>
        </div>

        {/* Loading */}
        {isLoading ? (
          <div className="eval-loader">Loading…</div>
        ) : (
          <div className="eval-table-wrapper">
            <table className="eval-table">
              <thead>
                <tr>
                  <th>APPLICANTNAME <span className="sort-icon">↑↓</span></th>
                  <th>POSITION TITLE <span className="sort-icon">↑↓</span></th>
                  <th>INTERVIEW DATE <span className="sort-icon">↑↓</span></th>
                  <th>INTERVIEW LEVELS <span className="sort-icon">↑↓</span></th>
                  <th>GRADE <span className="sort-icon">↑↓</span></th>
                  <th>ATTACHMENTS</th>
                  <th>STATUS</th>
                  <th>ACTION</th>
                </tr>
              </thead>
              <tbody>
                {candidates.length === 0 ? (
                  <tr>
                    <td colSpan={8} className="eval-table__empty">
                      No candidates found for evaluation.
                    </td>
                  </tr>
                ) : (
                  candidates.map((row:any) => (
                    <tr key={row.ID}>
                      {/* Applicant Name */}
                      <td className="eval-col-name">{row.ApplicantName}</td>

                      {/* Position Title */}
                      <td className="eval-col-position">{row.PositionTitle}</td>

                      {/* Interview Date & Time */}
                      <td className="eval-col-date">{row.InterviewDateTime}</td>

                      {/* Interview Level – e.g. "Level 1" or "Level 1 & 2" */}
                      <td className="eval-col-level">{row.InterviewLevel}</td>

                      {/* Grade */}
                      <td className="eval-col-grade">
                        <span>{row.Grade}</span>
                      </td>

                      {/* Attachments – hover triggers handleHover for tooltip */}
                      <td
                        className="eval-col-attachments"
                        onMouseEnter={() => handleHover(row.StatusId, row)}
                        title={
                          pendingInfo.length > 0
                            ? `Pending: ${pendingInfo.length} evaluator(s)`
                            : "No pending info"
                        }
                      >
                        <span className="attach-icon">📎</span>
                        <span className="attach-count">
                          {pendingInfo.length || "—"}
                        </span>
                      </td>

                      {/* Status with blue dot badge */}
                      <td className="eval-col-status">
                        <span className="status-badge">
                          <span className="status-dot" />
                          {row.Status}
                        </span>
                      </td>

                      {/* Action – EVALUATE button */}
                      <td className="eval-col-action">
                        <button
                          className="evaluate-btn"
                          onClick={() => onEvaluate(row)}
                        >
                          EVALUATE
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default EvaluationTab;